package com.gamehub.application.service; import com.gamehub.application.OperationsService; import java.util.List; public final class MaintenanceService { private final OperationsService ops; public MaintenanceService(OperationsService ops){this.ops=ops;} public List<String> stations()throws Exception{return ops.stationRecords();} public List<String> tickets()throws Exception{return ops.maintenanceTickets();} public long report(long a,long s,String sev,String d)throws Exception{return ops.openMaintenance(a,s,sev,d);} public void update(long a,long t,String st,String n,boolean ready)throws Exception{ops.updateMaintenance(a,t,st,n,ready);} }